28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "title")
41	    private String title;
42	
43	    @Column(name = "address")
44	    @NotEmpty
45	    private String address;
46	
47	    @Column(name = "address_line1")
48	    private String addressLine1;
49	
50	    @Column(name = "address_line2")
51	    private String addressLine2;
52	
53	    @Column(name = "city")
54	    @NotEmpty
55	    private String city;
56	
57	    @Column(name = "telephone")
58	    @NotEmpty
59	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ and 8 to 15 digits)")
60	    private String telephone;
61	
62	    @Column(name = "email")
63	    private String email;
64	
65	    @Column(name = "postcode")
66	    private String postcode;
67	
68	    @Column(name = "registration_date", columnDefinition = "DATE")
69	    private LocalDate registrationDate;
70	
71	    @Column(name = "birth_date", columnDefinition = "DATE")
72	    private LocalDate birthDate;
73	
74	    @Column(name = "customer_code")
75	    private String customerCode;
76	
77	    @Column(name = "household_id")
78	    private String householdId;
79	
80	    @Column(name = "namesake_count")
81	    private Integer namesakeCount;
82	
83	    @Column(name = "household_size")
84	    private Integer householdSize;
85	
86	    @Column(name = "bulk_signup_warning")
87	    private boolean bulkSignupWarning;
88	
89	    @Column(name = "possible_duplicate")
90	    private boolean possibleDuplicate;
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @Column(name = "deleted")
96	    private boolean deleted;
97	
98	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
99	    private Set<Pet> pets;
100	
101	    public String getTitle() {
102	        return this.title;
103	    }
104	
105	    public void setTitle(String title) {
106	        this.title = title;
107	    }
108	
109	    /**
110	     * The owner's salutation: the {@link #title} followed by a space and the last name when a title
111	     * is supplied, otherwise just the last name.
112	     */
113	    @Transient
114	    public String getSalutation() {
115	        return (this.title == null || this.title.isBlank())
116	            ? this.lastName
117	            : this.title + " " + this.lastName;
118	    }
119	
120	    public String getAddress() {
121	        return this.address;
122	    }
123	
124	    public void setAddress(String address) {
125	        this.address = address;
126	    }
127	
128	    public String getAddressLine1() {
129	        return this.addressLine1;
130	    }
131	
132	    public void setAddressLine1(String addressLine1) {
133	        this.addressLine1 = addressLine1;
134	    }
135	
136	    public String getAddressLine2() {
137	        return this.addressLine2;
138	    }
139	
140	    public void setAddressLine2(String addressLine2) {
141	        this.addressLine2 = addressLine2;
142	    }
143	
144	    public String getCity() {
145	        return this.city;
146	    }
147	
148	    public void setCity(String city) {
149	        this.city = city;
150	    }
151	
152	    public String getTelephone() {
153	        return this.telephone;
154	    }
155	
156	    public void setTelephone(String telephone) {
157	        this.telephone = telephone;
158	    }
159	
160	    public String getEmail() {
161	        return this.email;
162	    }
163	
164	    /**
165	     * Stores the email in its canonical lower-cased form so it is always persisted and
166	     * returned lower-cased, regardless of the casing supplied by the client.
167	     */
168	    public void setEmail(String email) {
169	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
170	    }
171	
172	    public String getPostcode() {
173	        return this.postcode;
174	    }
175	
176	    public void setPostcode(String postcode) {
177	        this.postcode = postcode;
178	    }
179	
180	    public LocalDate getRegistrationDate() {
181	        return this.registrationDate;
182	    }
183	
184	    public void setRegistrationDate(LocalDate registrationDate) {
185	        this.registrationDate = registrationDate;
186	    }
187	
188	    public LocalDate getBirthDate() {
189	        return this.birthDate;
190	    }
191	
192	    public void setBirthDate(LocalDate birthDate) {
193	        this.birthDate = birthDate;
194	    }
195	
196	    /**
197	     * The fiscal year of the owner's {@link #registrationDate}, as the {@code "FY<YY>"} label of the
198	     * fiscal year (starting 1 July) that contains the business-day-adjusted registration date.
199	     */
200	    @Transient
201	    public String getFiscalYear() {
202	        return FiscalYear.label(this.registrationDate);
203	    }
204	
205	    /**
206	     * The owner's tenure in fiscal years: the number of fiscal years elapsed from its
207	     * {@link #registrationDate} to the current date. An owner registered in the current fiscal year
208	     * has zero tenure.
209	     */
210	    @Transient
211	    public int getTenureFiscalYears() {
212	        return FiscalYear.yearsBetween(this.registrationDate, LocalDate.now());
213	    }
214	
215	    /**
216	     * The owner's age band derived from {@link #birthDate} against {@link #registrationDate}, or
217	     * {@code null} when no birth date was supplied.
218	     */
219	    @Transient
220	    public AgeBand getAgeBand() {
221	        return this.birthDate == null ? null : AgeBand.of(this.birthDate, this.registrationDate);
222	    }
223	
224	    public String getCustomerCode() {
225	        return this.customerCode;
226	    }
227	
228	    public void setCustomerCode(String customerCode) {
229	        this.customerCode = customerCode;
230	    }
231	
232	    public String getHouseholdId() {
233	        return this.householdId;
234	    }
235	
236	    public void setHouseholdId(String householdId) {
237	        this.householdId = householdId;
238	    }
239	
240	    public Integer getNamesakeCount() {
241	        return this.namesakeCount;
242	    }
243	
244	    public void setNamesakeCount(Integer namesakeCount) {
245	        this.namesakeCount = namesakeCount;
246	    }
247	
248	    public Integer getHouseholdSize() {
249	        return this.householdSize;
250	    }
251	
252	    public void setHouseholdSize(Integer householdSize) {
253	        this.householdSize = householdSize;
254	    }
255	
256	    public boolean isBulkSignupWarning() {
257	        return this.bulkSignupWarning;
258	    }
259	
260	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
261	        this.bulkSignupWarning = bulkSignupWarning;
262	    }
263	
264	    public boolean isPossibleDuplicate() {
265	        return this.possibleDuplicate;
266	    }
267	
268	    public void setPossibleDuplicate(boolean possibleDuplicate) {
269	        this.possibleDuplicate = possibleDuplicate;
270	    }
271	
272	    public Integer getPossibleDuplicateOf() {
273	        return this.possibleDuplicateOf;
274	    }
275	
276	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
277	        this.possibleDuplicateOf = possibleDuplicateOf;
278	    }
279	
280	    /**
281	     * Whether this owner has been soft-deleted: the record is retained but flagged so it is
282	     * excluded from the create endpoint's duplicate and identity checks. A newly created owner
283	     * is not deleted.
284	     */
285	    public boolean isDeleted() {
286	        return this.deleted;
287	    }
288	
289	    public void setDeleted(boolean deleted) {
290	        this.deleted = deleted;
291	    }
292	
293	    /**
294	     * The derived key that uniquely identifies an owner for duplicate detection: the normalized
295	     * telephone, the (lower-cased) email or the empty string when absent, and the household id or
296	     * the empty string when the owner belongs to no household, joined with {@code '|'}. Two owners
297	     * are duplicates only when their whole identity keys are equal, so members of the same household
298	     * with different telephones (or an owner reusing only a telephone or only an email) remain
299	     * distinct.
300	     */
301	    @Transient
302	    public String getIdentityKey() {
303	        return this.telephone + "|"
304	            + (this.email == null ? "" : this.email) + "|"
305	            + (this.householdId == null ? "" : this.householdId);
306	    }
307	
308	    /**
309	     * On first persist, default the registration date to the server's current date when the
310	     * client did not supply one, then roll the effective date forward so it always falls on a
311	     * business day (a weekend moves to the following Monday).
312	     */
313	    @PrePersist
314	    private void defaultRegistrationDate() {
315	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
316	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
317	    }
318	
319	    protected Set<Pet> getPetsInternal() {
320	        if (this.pets == null) {
321	            this.pets = new HashSet<>();
322	        }
323	        return this.pets;
324	    }
325	
326	    protected void setPetsInternal(Set<Pet> pets) {
327	        this.pets = pets;
328	    }
329	
330	    public List<Pet> getPets() {
331	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
332	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
333	        return Collections.unmodifiableList(sortedPets);
334	    }
335	
336	    public void setPets(List<Pet> pets) {
337	        this.pets = new HashSet<>(pets);
338	    }
339	
340	    public void addPet(Pet pet) {
341	        getPetsInternal().add(pet);
342	        pet.setOwner(this);
343	    }
344	
345	    /**
346	     * Return the Pet with the given name, or null if none found for this Owner.
347	     *
348	     * @param name to test
349	     * @return true if pet name is already in use
350	     */
351	    public Pet getPet(String name) {
352	        return getPet(name, false);
353	    }
354	
355	    /**
356	     * Return the Pet with the given name, or null if none found for this Owner.
357	     *
358	     * @param name to test
359	     * @return true if pet name is already in use
360	     */
361	    public Pet getPet(String name, boolean ignoreNew) {
362	        name = name.toLowerCase();
363	        for (Pet pet : getPetsInternal()) {
364	            if (!ignoreNew || !pet.isNew()) {
365	                String compName = pet.getName();
366	                compName = compName.toLowerCase();
367	                if (compName.equals(name)) {
368	                    return pet;
369	                }
370	            }
371	        }
372	        return null;
373	    }
374	
375	    public Pet getPet(Integer petId) {
376	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
377	    }
378	
379	    @Override
380	    public String toString() {
381	        return new ToStringCreator(this)
382	
383	            .append("id", this.getId())
384	            .append("new", this.isNew())
385	            .append("lastName", this.getLastName())
386	            .append("firstName", this.getFirstName())
387	            .append("address", this.address)
388	            .append("city", this.city)
389	            .append("telephone", this.telephone)
390	            .append("email", this.email)
391	            .toString();
392	    }
393	}
