44	    Owner toOwner(OwnerDto ownerDto);
45	
46	    /**
47	     * Formats the owner's canonical API self link as {@code "/api/owners/<id>"}.
48	     */
49	    default String formatSelfLink(Owner owner) {
50	        return "/api/owners/" + owner.getId();
