52	
53	    /**
54	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
55	     */
56	    default String formatDisplayName(Owner owner) {
57	        return owner.getLastName() + ", " + owner.getFirstName();
58	    }
59	
60	    /**
61	     * Formats the owner's stored E.164 telephone for human display (country code, a space and the
62	     * national digits grouped in threes), leaving the raw {@code telephone} in E.164 form.
63	     */
64	    default String formatTelephoneDisplay(Owner owner) {
65	        return TelephoneFormatter.toDisplay(owner.getTelephone());
66	    }
67	
68	    /**
69	     * Formats the owner's initials as the upper-cased first letters of firstName and
70	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
71	     */
72	    default String formatInitials(Owner owner) {
73	        return initial(owner.getFirstName()) + initial(owner.getLastName());
74	    }
75	
76	    /** The upper-cased first letter of {@code name} followed by a dot. */
77	    private String initial(String name) {
78	        return Character.toUpperCase(name.charAt(0)) + ".";
79	    }
80	
81	    /**
82	     * Derives the owner's locality (canonical region) from the leading {@code <REGION>} segment of
83	     * its {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality always agrees with the
84	     * region encoded in the owner's identity.
85	     */
86	    default String resolveLocality(Owner owner) {
87	        String customerCode = owner.getCustomerCode();
88	        return customerCode.substring(0, customerCode.indexOf('-'));
89	    }
90	
91	    /**
92	     * Derives the owner's IANA timezone from its {@linkplain #resolveLocality(Owner) locality}
93	     * (canonical region) via the fixed region-to-timezone table, or {@code null} when the locality
94	     * has no known timezone.
95	     */
96	    default String resolveTimezone(Owner owner) {
97	        return TimezoneResolver.resolve(resolveLocality(owner));
98	    }
99	
100	    /**
101	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
102	     * last two digits of the {@linkplain Owner#getFiscalYear() fiscal year} of the registration
103	     * date, e.g. {@code "LON-SMI-0007-M26"}.
104	     */
105	    default String formatMembershipNumber(Owner owner) {
106	        return owner.getCustomerCode() + "-M" + owner.getFiscalYear().substring(2);
107	    }
108	
109	    /**
110	     * Computes the Luhn check digit over the decimal digits of the owner's customer code.
111	     */
112	    default Integer computeCheckDigit(Owner owner) {
113	        return Luhn.checkDigit(owner.getCustomerCode());
114	    }
115	
116	    /** The minimum tenure, in fiscal years, an owner must exceed to earn the tenure membership points. */
117	    int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
118	
119	    /** The minimum household size that earns the household membership points. */
120	    int HOUSEHOLD_POINTS_THRESHOLD = 3;
121	
122	    /**
123	     * Resolves the owner's membership points: starts at {@code 0}, plus {@code 2} when an email is
124	     * present, plus {@code 1} when the owner has no namesakes (namesakeCount is 0), plus {@code 2}
125	     * when the owner belongs to a household of {@value #HOUSEHOLD_POINTS_THRESHOLD} or more, plus
126	     * {@code 3} when the owner's tenure exceeds {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS} fiscal year.
127	     */
128	    default Integer resolveMembershipPoints(Owner owner) {
129	        int points = 0;
130	        if (hasEmail(owner)) {
131	            points += 2;
132	        }
133	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
134	            points += 1;
135	        }
136	        Integer householdSize = owner.getHouseholdSize();
137	        if (householdSize != null && householdSize >= HOUSEHOLD_POINTS_THRESHOLD) {
138	            points += 2;
139	        }
140	        if (owner.getTenureFiscalYears() > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
141	            points += 3;
142	        }
143	        return points;
144	    }
145	
146	    /**
147	     * Resolves the owner's numeric membership level from its {@linkplain #resolveMembershipPoints
148	     * membership points}: level {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
149	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more.
150	     */
151	    default Integer resolveMembershipLevel(Owner owner) {
152	        int points = resolveMembershipPoints(owner);
153	        if (points <= 1) {
154	            return 1;
155	        }
156	        if (points <= 3) {
157	            return 2;
158	        }
159	        if (points <= 5) {
160	            return 3;
161	        }
162	        return 4;
163	    }
164	
165	    /**
166	     * Resolves the owner's preferred contact channel: {@code "EMAIL"} when an email is
167	     * present, otherwise {@code "PHONE"}.
168	     */
169	    default String resolveContactPreference(Owner owner) {
170	        return hasEmail(owner) ? "EMAIL" : "PHONE";
171	    }
172	
173	    /** Whether the owner has a non-blank email address. */
174	    private boolean hasEmail(Owner owner) {
