271	     * name (ignoring case) and postcode but carrying a different telephone, so it is not a hard
272	     * identity-key duplicate. Returns the matching owner's id (the lowest when several match), or
273	     * {@code null} when the owner has no postcode or nothing matches.
274	     */
275	    @Override
276	    @Transactional(readOnly = true)
277	    public Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException {
278	        if (owner.getPostcode() == null) {
279	            return null;
280	        }
281	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
282	            .filter(existing -> !existing.isDeleted())
283	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
284	            .filter(existing -> !Objects.equals(owner.getTelephone(), existing.getTelephone()))
285	            .map(Owner::getId)
286	            .min(Integer::compareTo)
287	            .orElse(null);
288	    }
