13	public class AddressFormValidator implements ConstraintValidator<ValidAddress, OwnerFieldsDto> {
14	
15	    @Override
16	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
17	        if (owner == null || hasText(owner.getAddressLine1()) || hasText(owner.getAddress())) {
18	            return true;
19	        }
