17	package org.springframework.samples.petclinic.util;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.Set;
22	
23	/**
24	 * Utility for aligning dates to business days.
25	 */
26	public final class BusinessDay {
27	
28	    /**
29	     * Fixed public holidays that are not business days. A registration date landing on one of
30	     * these rolls forward to the next non-holiday weekday.
31	     */
32	    private static final Set<LocalDate> HOLIDAYS = Set.of(
33	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
34	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
35	
36	    private BusinessDay() {
37	    }
38	
39	    /**
40	     * Roll {@code date} forward to the next business day: any Saturday, Sunday or listed public
41	     * holiday moves to the following non-holiday weekday, while any other weekday is returned
42	     * unchanged.
43	     *
44	     * @param date the date to align
45	     * @return the same date when it already falls on a business day, otherwise the next business day
46	     */
47	    public static LocalDate rollForward(LocalDate date) {
48	        LocalDate rolled = date;
49	        while (!isBusinessDay(rolled)) {
50	            rolled = rolled.plusDays(1);
51	        }
52	        return rolled;
53	    }
54	
55	    private static boolean isBusinessDay(LocalDate date) {
56	        DayOfWeek dayOfWeek = date.getDayOfWeek();
57	        return dayOfWeek != DayOfWeek.SATURDAY && dayOfWeek != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
58	    }
59	}
